          if (type === "bird") this.critters.push({ type, x: X0 - 20, y: Y0 + 40 + this.rand() * (H * 0.4), vx: t.speed * 4, vy: (this.rand() - 0.5) * 0.4, ttl: t.ttl, ph: 0 });
